return ['x-generator'=>'GlotPress/4.0.3','translation-revision-date'=>'2026-01-07 12:53:44+0000','plural-forms'=>'nplurals=2; plural=n != 1;','project-id-version'=>'Plugins - BackWPup – WordPress Backup &amp; Restore Plugin - Stable (latest release)','language'=>'es','messages'=>['BackWPup 5.2.2 is here!'=>'¡BackWPup 5.2.2 ya está aquí!','At least one storage is required for a job to run'=>'Se requiere al menos un almacenamiento para ejecutar un trabajo','Job id not set'=>'ID del trabajo no establecido','Storage not found'=>'Almacenamiento no encontrado','Storage not set'=>'Almacenamiento no establecido','Failed to revoke Dropbox token: %s'=>'No se pudo revocar el token de Dropbox: %s','Configure'=>'Configurar','We’ve listened to your feedback and are happy to announce that this new version brings back the option to pick the exact day for monthly backups, 
